args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?person ?label ?bd ?bdRaw WHERE {
  VALUES ?person { <http://dbpedia.org/resource/Pattom_A._Thanu_Pillai> <http://dbpedia.org/resource/Francesco_Boccapaduli> }
  OPTIONAL { ?person dbo:birthDate ?bd }
  OPTIONAL { ?person dbp:birthDate ?bdRaw }
  OPTIONAL { ?person rdfs:label ?label FILTER(lang(?label) = 'en') }
}
ORDER BY ?bd

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?older ?olderLabel ?olderBirth WHERE {
  BIND(<http://dbpedia.org/resource/Francesco_Boccapaduli> AS ?a)
  BIND(<http://dbpedia.org/resource/Pattom_A._Thanu_Pillai> AS ?b)
  ?a dbo:birthDate ?aBirth .
  ?b dbo:birthDate ?bBirth .
  {
    FILTER(?aBirth < ?bBirth)
    BIND(?a AS ?older)
    BIND(?aBirth AS ?olderBirth)
  } UNION {
    FILTER(?bBirth < ?aBirth)
    BIND(?b AS ?older)
    BIND(?bBirth AS ?olderBirth)
  }
  OPTIONAL { ?older rdfs:label ?olderLabel FILTER(lang(?olderLabel) = 'en') }
}
LIMIT 1

